const lessons = [
  { title: 'Kenali kubusmu', short: 'Dasar & notasi', lead: 'Setiap sisi punya pusat warna yang tetap. Mulailah dengan mengenal arah sebelum mencoba menyelesaikannya.', observe: 'Pusat menentukan warna akhir sebuah sisi. Sudut punya 3 warna, rusuk punya 2 warna.', instruction: 'Coba gerakan kanan–atas yang sering dipakai dalam banyak algoritma.', algorithm: ['R','U','R\'','U\''], tip: 'Huruf tanpa tanda petik berarti searah jarum jam jika sisi itu menghadapmu.' },
  { title: 'Buat salib putih', short: 'Lapisan pertama', lead: 'Kumpulkan empat rusuk putih di sekitar pusat putih, lalu cocokkan warna sampingnya dengan pusat.', observe: 'Salib putih yang benar juga membentuk garis warna yang sama pada sisi-sisi samping.', instruction: 'Jika rusuk putih ada di depan atas dan sejajar dengan pusat samping, putar sisi depan dua kali untuk memasukkannya ke bawah.', algorithm: ['F2'], tip: 'Kerjakan satu rusuk dulu. Jangan hanya melihat warna putihnya; lihat juga warna pasangannya.' },
  { title: 'Lengkapi sudut putih', short: 'Lapisan pertama', lead: 'Masukkan empat sudut putih agar seluruh lapisan pertama selesai.', observe: 'Tempatkan sudut target tepat di atas slot yang warnanya cocok sebelum memasukkannya.', instruction: 'Ulangi gerakan kanan–atas sampai sudut masuk dengan orientasi yang tepat.', algorithm: ['R','U','R\'','U\''], tip: 'Jika sudut sudah di bawah tetapi terbalik, keluarkan dulu dengan algoritma yang sama.' },
  { title: 'Isi lapisan tengah', short: 'Lapisan kedua', lead: 'Pindahkan rusuk tanpa kuning dari lapisan atas ke sisi kanan atau kiri lapisan tengah.', observe: 'Cari rusuk di atas yang tidak mengandung warna kuning, lalu sejajarkan sisi depannya.', instruction: 'Algoritma berikut memasukkan rusuk dari atas ke slot kanan.', algorithm: ['U','R','U\'','R\'','U\'','F\'','U','F'], tip: 'Jika rusuk tujuan ada di kiri, gunakan versi cermin: U’ L’ U L U F U’ F’.' },
  { title: 'Bentuk salib kuning', short: 'Lapisan terakhir', lead: 'Sekarang fokus pada empat rusuk kuning di sisi atas. Posisi sampingnya belum harus benar.', observe: 'Pola titik, garis, atau siku memberi tahu berapa kali algoritma perlu diulang.', instruction: 'Pegang garis secara mendatar atau siku di kiri atas, lalu jalankan algoritma.', algorithm: ['F','R','U','R\'','U\'','F\''], tip: 'Setelah setiap pengulangan, lihat lagi pola kuning di atas sebelum mengulang.' },
  { title: 'Hadapkan sisi kuning', short: 'Lapisan terakhir', lead: 'Putar sudut-sudut lapisan atas hingga seluruh permukaan atas berwarna kuning.', observe: 'Perhatikan jumlah stiker kuning yang menghadap ke atas dan arah sudut yang belum tepat.', instruction: 'Latih pola “Sune” berikut. Posisikan kubus sesuai kasus sebelum menjalankannya.', algorithm: ['R','U','R\'','U','R','U2','R\''], tip: 'U2 artinya sisi atas diputar 180°. Gunakan tombol U dua kali saat mencoba manual.' },
  { title: 'Posisikan sudut kuning', short: 'Lapisan terakhir', lead: 'Setelah sisi atas kuning, pindahkan sudut-sudutnya ke tempat yang sesuai dengan warna samping.', observe: 'Cari dua sudut yang warnanya cocok pada satu sisi. Hadapkan pasangan itu ke kiri.', instruction: 'Jalankan pola penukar sudut ini. Sisi kuning bisa berubah sementara; ulangi pola dari langkah sebelumnya untuk mengembalikannya.', algorithm: ['F\'','L','F\'','R2','F','L\'','F\'','R2','F2'], tip: 'Jika belum ada dua sudut yang cocok, jalankan pola satu kali lalu cari pasangannya lagi.' },
  { title: 'Tukar rusuk terakhir', short: 'Kubus selesai', lead: 'Tinggal rusuk-rusuk kuning di lapisan atas. Pindahkan ke pusat warna yang cocok untuk menyelesaikan kubus.', observe: 'Cari satu sisi samping yang sudah cocok, lalu amati arah tiga rusuk lainnya harus berpindah.', instruction: 'Latih pola penukar rusuk berikut. Sesuaikan sisi depan dengan kasus yang sedang kamu hadapi.', algorithm: ['F2','U','L','R\'','F2','L\'','R','U','F2'], tip: 'Periksa kecocokan warna samping setelah satu kali pola. Putar U bila perlu sebelum mengulang.' }
];

const color = {front:'#ec594f',back:'#f7a042',right:'#4a88e9',left:'#60c284',top:'#f2d653',bottom:'#f5f6e8'};
const faceMeta = CubeState.faceMeta;
const identity = [1,0,0,0,1,0,0,0,1];
const els = Object.fromEntries(['cube','cube-wrap','lesson-list','progress-text','progress-fill','simulator-title','lesson-count','guide-badge','guide-title','guide-lead','guide-observation','guide-instruction','algorithm','guide-tip','move-grid','run-button','next-button','scramble-button','reset-button','undo-button','announcement'].map(id=>[id,document.getElementById(id)]));
let cubies=[];
let currentLesson=0;
let completed=new Set();
let history=[];
let busy=false;
let viewX=-25,viewY=-35;
let drag=null;
const savedProgress=localStorage.getItem('cuber-progress');
if(savedProgress){try{completed=new Set(JSON.parse(savedProgress).filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length));}catch{}}

function makeCubie(x,y,z){
  const element=document.createElement('div');element.className='cubie';
  const faces=[['front',z===1],['back',z===-1],['right',x===1],['left',x===-1],['top',y===-1],['bottom',y===1]];
  for(const [name,visible] of faces){const face=document.createElement('div');face.className=`cubie-face ${name}${visible?'':' blank'}`;if(visible)face.style.setProperty('--sticker',color[name]);element.append(face);}
  els.cube.append(element);
  return {p:[x,y,z],o:[...identity],element};
}
function matrix(c){const o=c.o,[x,y,z]=c.p.map(n=>n*70);return `matrix3d(${o[0]},${o[3]},${o[6]},0,${o[1]},${o[4]},${o[7]},0,${o[2]},${o[5]},${o[8]},0,${x},${y},${z},1)`;}
function renderCube(instant=false){for(const c of cubies){if(instant)c.element.classList.add('no-transition');c.element.style.transform=matrix(c);}if(instant)requestAnimationFrame(()=>requestAnimationFrame(()=>cubies.forEach(c=>c.element.classList.remove('no-transition'))));}
function resetCube(){els.cube.replaceChildren();cubies=[];for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++)if(x||y||z)cubies.push(makeCubie(x,y,z));renderCube(true);viewX=-25;viewY=-35;updateView();history=[];announce('Kubus kembali ke posisi awal.');}
const rotateVector = CubeState.rotateVector;
function rotateMatrix(m,axis,dir){const columns=[[m[0],m[3],m[6]],[m[1],m[4],m[7]],[m[2],m[5],m[8]]].map(v=>rotateVector(v,axis,dir));return[columns[0][0],columns[1][0],columns[2][0],columns[0][1],columns[1][1],columns[2][1],columns[0][2],columns[1][2],columns[2][2]];}
function parseMove(move){const face=move[0];if(!faceMeta[face])return null;return{face,prime:move.includes("'"),twice:move.includes('2')};}
function applyQuarter(face,prime=false,instant=false){const {axis,layer,dir}=faceMeta[face];const direction=dir*(prime?-1:1);for(const c of cubies){if(c.p[axis]!==layer)continue;c.p=rotateVector(c.p,axis,direction);c.o=rotateMatrix(c.o,axis,direction);}renderCube(instant);}
function pause(ms){return new Promise(resolve=>setTimeout(resolve,ms));}
async function executeMove(move,{record=true,instant=false}={}){const parsed=parseMove(move);if(!parsed)return;const count=parsed.twice?2:1;for(let i=0;i<count;i++){applyQuarter(parsed.face,parsed.prime,instant);if(!instant)await pause(410);}if(record)history.push(move);announce(`Sisi ${parsed.face} diputar${parsed.prime?' berlawanan arah jarum jam':''}${parsed.twice?' dua kali':''}.`);}
async function runMoves(moves){if(busy)return;busy=true;setDisabled(true);for(const move of moves)await executeMove(move);busy=false;setDisabled(false);}
function setDisabled(value){for(const button of document.querySelectorAll('.move-button,.algorithm button'))button.disabled=value;for(const key of ['run-button','scramble-button','reset-button','undo-button'])els[key].disabled=value;}
function queueMove(move){if(busy)return;runMoves([move]);}
function announce(message){els.announcement.textContent=message;}
function saveProgress(){localStorage.setItem('cuber-progress',JSON.stringify([...completed]));}
function buildLessons(){els['lesson-list'].replaceChildren();lessons.forEach((lesson,index)=>{const button=document.createElement('button');button.className=`lesson-item${index===currentLesson?' active':''}${completed.has(index)?' done':''}`;button.type='button';button.setAttribute('aria-current',index===currentLesson?'step':'false');button.innerHTML=`<span class="lesson-number">${completed.has(index)?'✓':String(index+1).padStart(2,'0')}</span><span class="lesson-copy"><strong>${lesson.title}</strong><small>${lesson.short}</small></span><span class="lesson-arrow" aria-hidden="true">›</span>`;button.addEventListener('click',()=>selectLesson(index));els['lesson-list'].append(button);});}
function selectLesson(index){currentLesson=index;const lesson=lessons[index];buildLessons();els['simulator-title'].textContent=lesson.title;els['lesson-count'].textContent=`${String(index+1).padStart(2,'0')} / ${String(lessons.length).padStart(2,'0')}`;els['guide-badge'].textContent=`LANGKAH ${String(index+1).padStart(2,'0')}`;els['guide-title'].textContent=lesson.title;els['guide-lead'].textContent=lesson.lead;els['guide-observation'].textContent=lesson.observe;els['guide-instruction'].textContent=lesson.instruction;els['guide-tip'].textContent=lesson.tip;els.algorithm.replaceChildren();lesson.algorithm.forEach(move=>{const button=document.createElement('button');button.type='button';button.textContent=move.replace("'",'’');button.title=`Jalankan gerakan ${move}`;button.addEventListener('click',()=>queueMove(move));els.algorithm.append(button);});els['next-button'].innerHTML=index===lessons.length-1?'Tandai pelajaran selesai <span aria-hidden="true">✓</span>':'Tandai selesai & lanjut <span aria-hidden="true">→</span>';updateProgress();}
function updateProgress(){els['progress-text'].textContent=`${completed.size} dari ${lessons.length} langkah`;els['progress-fill'].style.width=`${completed.size/lessons.length*100}%`;}
function createMoves(){for(const face of ['F','R','U','L','D','B'])for(const prime of [false,true]){const button=document.createElement('button');button.className=`move-button${prime?' prime':''}`;button.type='button';button.textContent=face+(prime?'’':'');button.setAttribute('aria-label',`Putar sisi ${face} ${prime?'berlawanan':'searah'} jarum jam`);button.addEventListener('click',()=>queueMove(face+(prime?"'":'')));els['move-grid'].append(button);}}
function updateView(){els.cube.style.transform=`rotateX(${viewX}deg) rotateY(${viewY}deg) scale(var(--cube-scale))`;}
els['cube-wrap'].addEventListener('pointerdown',event=>{drag={x:event.clientX,y:event.clientY,viewX,viewY};els['cube-wrap'].setPointerCapture(event.pointerId);});
els['cube-wrap'].addEventListener('pointermove',event=>{if(!drag)return;viewY=drag.viewY+(event.clientX-drag.x)*.5;viewX=Math.max(-85,Math.min(85,drag.viewX-(event.clientY-drag.y)*.5));updateView();});
els['cube-wrap'].addEventListener('pointerup',()=>drag=null);els['cube-wrap'].addEventListener('pointercancel',()=>drag=null);
els['run-button'].addEventListener('click',()=>runMoves(lessons[currentLesson].algorithm));
els['next-button'].addEventListener('click',()=>{completed.add(currentLesson);saveProgress();if(currentLesson<lessons.length-1)selectLesson(currentLesson+1);else{selectLesson(currentLesson);announce('Selamat! Semua pelajaran selesai.');}document.getElementById('belajar').scrollIntoView({behavior:'smooth',block:'start'});});
els['reset-button'].addEventListener('click',()=>{if(!busy)resetCube();});
els['undo-button'].addEventListener('click',async()=>{if(busy||!history.length)return;const last=history.pop();const inverse=last.endsWith('2')?last:last.endsWith("'")?last[0]:last[0]+"'";busy=true;setDisabled(true);await executeMove(inverse,{record:false});busy=false;setDisabled(false);});
els['scramble-button'].addEventListener('click',()=>{if(busy)return;const sides=['F','R','U','L','D','B'];let previous='';for(let i=0;i<24;i++){let face;do{face=sides[Math.floor(Math.random()*sides.length)];}while(face===previous);previous=face;const move=face+(Math.random()<.5?"'":'');applyQuarter(face,move.includes("'"),true);history.push(move);}announce('Kubus diacak. Coba putar sisi untuk berlatih.');});
createMoves();resetCube();selectLesson(0);
